import{c as t,Q as a,j as i,m as n}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"GetAsinhTmpBufferFactorSize","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetAsinhTmpBufferFactorSize","slug":"getasinhtmpbufferfactorsize"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/数学计算/Asinh接口/GetAsinhTmpBufferFactorSize.md","filePath":"api/SIMD-API/高阶API/数学计算/Asinh接口/GetAsinhTmpBufferFactorSize.md"}'),s={name:"api/SIMD-API/高阶API/数学计算/Asinh接口/GetAsinhTmpBufferFactorSize.md"};function r(o,e,p,l,u,d){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="getasinhtmpbufferfactorsize" tabindex="-1">GetAsinhTmpBufferFactorSize <a class="header-anchor" href="#getasinhtmpbufferfactorsize" aria-label="Permalink to &quot;GetAsinhTmpBufferFactorSize&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>kernel侧Asinh接口的计算需要开发者预留/申请临时空间，最大临时空间（maxTmpBuffer）和输入所占空间（inputSize * typeSize）存在以下关系：</p><p><strong>maxTmpBuffer = maxLiveNodeCount * inputSize * typeSize + extraBuffer</strong></p><p>其中maxLiveNodeCount表示最大临时空间是输入所占空间的多少倍；extraBuffer表示使用的额外临时空间大小。</p><p>该接口用于获取maxLiveNodeCount和extraBuffer，在固定空间大小的情况下，通过maxLiveNodeCount和extraBuffer可以推算算子单次最大计算元素数量；另外，接口获取的maxLiveNodeCount值可能为0，计算时需要判断该值非0，避免除零错误。</p><p>示例如下：</p><p>算子实现需要调用Asinh接口，开发者为其预留currBuff大小的空间，利用GetAsinhTmpBufferFactorSize接口得到maxLiveNodeCount、extraBuffer输出值，反推Asinh算子单次最大计算元素数量为：</p><p><strong>currentShapeSize = (currBuff - extraBuffer) / maxLiveNodeCount / typeSize</strong></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetAsinhTmpBufferFactorSize(const uint32_t typeSize, uint32_t&amp; maxLiveNodeCount, uint32_t&amp; extraBuf)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数列表</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>功能</th></tr></thead><tbody><tr><td>typeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。比如输入的数据类型为half，此处应传入2。</td></tr><tr><td>maxLiveNodeCount</td><td>输出</td><td>最大存活节点数，最大临时空间是输入所占空间的多少倍。</td></tr><tr><td>extraBuf</td><td>输出</td><td>使用的额外临时空间大小，单位为字节。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>当利用maxLiveNodeCount，extraBuf反推出的currentShapeSize * typeSize &lt; 256B时，currentShapeSize按照256B/typeSize的值向上取整。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 获取输入类型为half的Asinh操作的maxLiveNodeCount和extraBuffer</span></span>
<span class="line"><span>uint32_t typeSize = sizeof(half);</span></span>
<span class="line"><span>uint32_t maxLiveNodeCount = 0;</span></span>
<span class="line"><span>uint32_t extraBuffer = 0;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::GetAsinhTmpBufferFactorSize(typeSize, maxLiveNodeCount, extraBuffer);</span></span></code></pre></div>`,20)])])}const c=t(s,[["render",r]]);export{f as __pageData,c as default};
